extends SceneTree
# How many glade bushes (Glade._build_bushes draws, seed 77) fell inside the mini range (before the move).
func _init() -> void:
	var trees := Grove.plan()
	var bays := RangeLayout.rect("glade")
	var rng := RandomNumberGenerator.new()
	rng.seed = 77
	var placed := 0
	var tries := 0
	var inside := 0
	var berries := 0
	while placed < Glade.BUSHES and tries < Glade.BUSHES * 20:
		tries += 1
		var a := rng.randf() * TAU
		var edge := rng.randf() < 0.6
		var r := rng.randf_range(Glade.CLEARING - 8.0, Glade.CLEARING + 14.0) if edge else rng.randf_range(6.0, Glade.FOREST_OUT - 12.0)
		var p := Vector2(cos(a), sin(a)) * r
		var roll := rng.randf()
		var kind := "berry" if r < Glade.CLEARING - 4.0 and roll < 0.6 else ("juniper" if roll < 0.45 else "hazel")
		rng.randi(); rng.randf(); rng.randf_range(0.8, 1.2)
		var ok := p.length() >= 5.0
		for d: Dictionary in trees:
			if p.distance_to(d.pos) < 2.5 + float(d.diameter) * 2.0:
				ok = false
		if not ok:
			continue
		placed += 1
		if bays.grow(0.7).has_point(p):
			inside += 1
			if kind == "berry":
				berries += 1
			print("BUSH in range: %s %s" % [kind, p])
	print("BUSH_CHECK rect=%s inside=%d berries=%d placed=%d" % [bays, inside, berries, placed])
	quit()
EOF
